example.code:
let nickname;
const middleName = null;

console.log(`nickname: ${nickname} (${typeof nickname})`);
console.log(`middleName: ${middleName} (${typeof middleName})`);
console.log(`null + 5 = ${null + 5}`);
console.log(`undefined + 5 = ${undefined + 5}`);

nickname = "Ace";
console.log(`nickname later: ${nickname} (${typeof nickname})`);

